(176,'model_year','CRF1000L Africa Twin — 2016 model-year factory specification','{"power":"70 kW at 7,500 rpm","gearbox":"Six-speed manual or optional DCT","torque_nm":98,"model_year":"2016","engine_type":"Liquid-cooled four-stroke 270-degree parallel twin","engine_capacity_cc":998,"fuel_capacity_litres":18.8}'::jsonb,2016,NULL,'Europe','Honda Global — 16YM CRF1000L Africa Twin, 16 October 2015','https://global.honda/en/newsroom/news/2015/2151016eng-crf1000l.html','manufacturer_primary_source_individual_model_checked_2026_11_12','Figures are Honda''s 2016 European model-year specifications, not claimed for subsequent CRF1100L or 2018+ CRF1000L revisions.','Honda Global — 16YM CRF1000L Africa Twin, 16 October 2015'),
